import { randomUUID } from "node:crypto";
import type { Page } from "@playwright/test";
import { and, eq } from "drizzle-orm";
import { studyItems } from "@/shared/db/schema";
import { createTestDb } from "../db/helpers/test-db";
import { expect, hasSupabaseEnv, signIn, test } from "./fixtures/auth";
import { createNotebookWithOpenPage } from "./helpers/notebooks";

// Phase 5 T6 exam session (documento-maestro §3.3, §7.5): a page with 10
// questions (generated by the fake AI provider, AI_PROVIDER_MODE=fake),
// the panel's Examen row (Phase 6 T5b), 10 questions answered one by
// one with the right/wrong reveal, 4 of them wrong → the results show 60 %,
// the total time and the failed concepts, and every root of the page is
// due tomorrow on the SM-2 engine (so the page shows in "Hoy" next day).
//
// The fake provider's question N ("Pregunta N: …") has its correct option
// at index (N - 1) % 4, so the spec can choose right or wrong on purpose.

const SENTENCES = [
  "La mitocondria produce la mayor parte del ATP de la célula.",
  "La membrana interna forma pliegues llamados crestas mitocondriales.",
  "La matriz mitocondrial contiene enzimas del ciclo de Krebs.",
].join(" ");
const WRONG_QUESTIONS = new Set([1, 2, 3, 4]);
const DAY_MS = 86_400_000;

// Optional: a directory to drop the screenshots in (visual check).
const SCREENSHOT_DIR = process.env.E2E_SCREENSHOT_DIR;

async function shot(page: Page, name: string) {
  if (!SCREENSHOT_DIR) return;
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${SCREENSHOT_DIR}/${name}.png` });
}

// Writes a page, generates its 10 fake questions, takes the exam from the
// techniques panel answering the questions in `wrong` wrong and the rest
// right, and finishes it: the results route is open on return.
async function takeExam(
  page: Page,
  wrong: ReadonlySet<number>,
  shotPrefix: string,
): Promise<{ notebookId: string; pageId: string }> {
  await createNotebookWithOpenPage(
    page,
    `Cuaderno examen ${randomUUID().slice(0, 8)}`,
  );
  const [, , notebookId, , pageId] = new URL(page.url()).pathname.split("/");

  const editable = page
    .getByTestId("editor-mount")
    .locator('[contenteditable="true"]');
  await editable.click();
  // Keys sent <15 ms after a click can precede Chrome's selectionchange.
  await page.waitForTimeout(100);
  await page.keyboard.type(SENTENCES);
  await expect(page.getByTestId("autosave-status")).toHaveText("guardado", {
    timeout: 15000,
  });

  const panel = page.getByTestId("techniques-panel");
  // Nothing generated yet: no exam row in the panel's generated list.
  await expect(panel.getByTestId("generated-item-exam")).toHaveCount(0);
  await panel.getByTestId("generate-exam-questions").click();
  // The count is chosen in the dialog (default 10).
  await page.getByTestId("confirm-exam-generation").click();
  await expect(panel.getByTestId("exam-generation-notice")).toHaveText(
    "Se generaron 10 preguntas.",
    { timeout: 30000 },
  );
  await expect(panel.getByTestId("generated-item-exam")).toContainText(
    "10 preguntas",
  );
  await panel.getByTestId("generated-item-exam").click();
  await expect(page).toHaveURL(`/exams/${notebookId}/${pageId}`);

  await expect(page.getByTestId("exam-session-count-value")).toHaveText("10");
  await shot(page, `${shotPrefix}start`);
  await page.getByTestId("start-exam-button").click();
  await expect(page.getByTestId("exam-session")).toBeVisible({
    timeout: 15000,
  });

  for (let n = 1; n <= 10; n += 1) {
    // The stem is "Pregunta N: …"; the progress labels have no colon.
    await expect(page.getByTestId("exam-answer-reveal")).toHaveCount(0);
    const stem = await page.getByTestId("exam-session").innerText();
    const number = Number(/Pregunta (\d+):/.exec(stem)?.[1]);
    expect(number).toBeGreaterThan(0);
    const correct = (number - 1) % 4;
    const choice = wrong.has(number) ? (correct + 1) % 4 : correct;
    await page
      .getByTestId("exam-options")
      .getByRole("button")
      .nth(choice)
      .click();
    const reveal = page.getByTestId("exam-answer-reveal");
    await expect(reveal).toContainText(
      wrong.has(number) ? "Incorrecto" : "¡Correcto!",
      { timeout: 15000 },
    );
    if (n === 1) await shot(page, `${shotPrefix}question-answered`);
    if (n < 10) await page.getByTestId("next-question-button").click();
  }

  await page.getByTestId("finish-exam-button").click();
  await expect(page).toHaveURL(
    new RegExp(`/exams/${notebookId}/${pageId}/resultados\\?sesion=`),
    // Grading records 10 SM-2 reviews over the single remote connection.
    { timeout: 60000 },
  );
  return { notebookId: notebookId as string, pageId: pageId as string };
}

test.describe("exam session", () => {
  test.skip(!hasSupabaseEnv, "Supabase env (cogni-dev) is not configured");

  // A test-scoped user: the fake AI daily limit (6 per owner, in server
  // memory) would otherwise be shared with every AI-spending spec in the
  // worker and run out depending on spec order.
  test.beforeEach(async ({ page, freshUser }) => {
    await signIn(page, freshUser);
  });

  test("takes a 10-question exam, fails it and schedules the page for tomorrow", async ({
    page,
  }) => {
    test.setTimeout(180_000);
    const { pageId, notebookId } = await takeExam(page, WRONG_QUESTIONS, "");
    const results = page.getByTestId("exam-results");
    await expect(results).toContainText("60%");
    await expect(results).toContainText("6 / 10");
    await expect(results).toContainText(/Tiempo\s*\d{2}:\d{2}/);
    await expect(page.getByTestId("exam-failed")).toBeVisible();
    // The fake questions may share a concept: each failed one is listed once.
    await expect(page.getByTestId("exam-failed-concepts")).toBeVisible();
    await expect(page.getByTestId("exam-review-row")).toHaveCount(10);
    await expect(
      page.getByTestId("exam-review-row").filter({ hasText: "Incorrecta" }),
    ).toHaveCount(4);
    await shot(page, "results-fail");

    // Every root was reviewed when the exam closed: the wrong ones with
    // q = 1 and all of them due about a day later.
    const db = createTestDb();
    try {
      const items = await db
        .select()
        .from(studyItems)
        .where(
          and(
            eq(studyItems.pageId, pageId as string),
            eq(studyItems.kind, "exam_question"),
          ),
        );
      expect(items).toHaveLength(10);
      expect(items.filter((item) => item.lastQuality === 1)).toHaveLength(4);
      const now = Date.now();
      for (const item of items) {
        expect(item.dueAt.getTime()).toBeGreaterThan(now + DAY_MS - 3_600_000);
        expect(item.dueAt.getTime()).toBeLessThan(now + DAY_MS + 3_600_000);
      }
    } finally {
      await db.$client.end();
    }

    // The failed page waits for its retake (T7): no new normal exam.
    await page.goto(`/exams/${notebookId}/${pageId}`);
    await expect(page.getByTestId("exam-retake")).toBeVisible();
    await expect(page.getByTestId("start-exam-button")).toHaveCount(0);
  });

  test("passes an exam and offers a new one", async ({ page }) => {
    test.setTimeout(180_000);
    const { notebookId, pageId } = await takeExam(page, new Set([1]), "pass-");
    const results = page.getByTestId("exam-results");
    await expect(results).toContainText("90%");
    await expect(page.getByTestId("exam-passed")).toBeVisible();
    await shot(page, "results-pass");
    await page.getByTestId("new-exam-link").click();
    await expect(page).toHaveURL(`/exams/${notebookId}/${pageId}`);
    await expect(page.getByTestId("start-exam-button")).toBeVisible();
  });
});
